import {receiveGamePackage,appendGameAction,buildGameReceipt,gameMode,gameValues,type GamePackage,type GameAction} from '../domain/gameProtocol';
import {startTrialVerified} from '../domain/runtimeVerified';
import {stepTrial,getTrialChoices,getTrialNode,declaredEntrypoints,type TrialSession,type TrialRequest} from '../domain/runtime';
import {parseStrictJson,jsonBytes,sha256} from '../storage/json';
import {presentationAnchorApplies} from '../domain/presentation';
import {richBody} from './richBody';
import {materialView} from './material';
const root=document.getElementById('game-receiver');
if(root){
 let pkg:GamePackage|undefined,actions:GameAction[]=[],requests:TrialRequest[]=[],session:TrialSession|undefined,busy=false;
 const heading=document.createElement('h1');heading.textContent='独立ブラウザーゲーム受取例';root.append(heading);
 const note=document.createElement('p');note.textContent='出力したruntime.jsonを選び、このゲームで結果を測定してから物語を開始します。受領と結果の証跡は作者がファイルで戻します。';root.append(note);
 const file=document.createElement('input');file.type='file';file.accept='.json,application/json';file.setAttribute('aria-label','ゲームが受け取るruntime.json');root.append(file);
 const status=document.createElement('p');status.setAttribute('role','status');root.append(status);
 const entries=document.createElement('select');entries.setAttribute('aria-label','ゲーム開始入口');root.append(entries);
 const tick=document.createElement('input');tick.setAttribute('aria-label','ゲーム開始の世界内tick');tick.placeholder='世界内tick（整数）';root.append(tick);let initialTick:string|undefined;const urls=new Set<string>();
 const controls=document.createElement('div');root.append(controls);const content=document.createElement('div');root.append(content);const path=document.createElement('div');root.append(path);
 function button(parent:HTMLElement,text:string,action:()=>Promise<void>|void,disabled=false){const b=document.createElement('button');b.type='button';b.textContent=text;b.disabled=busy||disabled;b.onclick=()=>{if(busy)return;busy=true;render();void Promise.resolve().then(action).catch(cause=>status.textContent=(cause as Error).message).finally(()=>{busy=false;render();});};parent.append(b);}
 function media(id:string|null|undefined){if(id&&pkg)materialView(pkg.runtimeProject,pkg.assetData??{},pkg.publicToRuntime,urls)(id,pkg.runtimeProject.projectId,content);}
 function render(){for(const url of urls)URL.revokeObjectURL(url);urls.clear();controls.replaceChildren();path.replaceChildren();file.disabled=busy;entries.disabled=busy||!!session;tick.disabled=busy||!!session;if(!pkg)return;
  for(const c of pkg.entities.filter(e=>e.kind==='external_contract')){const native=pkg.runtimeProject.entities.find(e=>e.id===pkg!.publicToRuntime[c.id]);if(native?.kind!=='external_contract')continue;const title=document.createElement('p');title.textContent=`外部契約 ${c.id} · 管理元${native.data.owner} · 仕様${native.data.version??'1.0.0'} · ${native.data.outputType}`;controls.append(title);if(native.data.owner==='game')for(const [action,label]of [['win','ゲームで勝利'],['lose','ゲームで敗退'],['collect','ゲームで物品を獲得']]as const)button(controls,`${label} (${c.id})`,async()=>{actions.push(await appendGameAction(pkg!,actions,c.id,action));status.textContent=`ゲーム操作${actions.length}回 · ${gameMode(actions)}`;},!!session);for(const [index,value]of(native.data.stubValues??[]).entries())button(controls,`宣言仮値 ${index+1}: ${JSON.stringify(value)} (${c.id})`,async()=>{actions.push(await appendGameAction(pkg!,actions,c.id,'stub',index));status.textContent=`仮入力を含む操作${actions.length}回 · ${gameMode(actions)}`;},!!session);}
  button(controls,'測定結果でゲームの物語を開始',async()=>{requests=[];initialTick=tick.value||undefined;session=await startTrialVerified(pkg!.runtimeProject,{entryId:entries.value,worldTick:initialTick,externalValues:gameValues(pkg!,actions)});status.textContent=`受領hash確認済み · ${gameMode(actions)} · ${session.status}`;},!!session);
  if(session){content.replaceChildren();const node=getTrialNode(pkg.runtimeProject,session),scene=session.content.entities.find(e=>e.id===node?.data.sceneId);if(scene?.kind==='scene'){richBody(pkg.runtimeProject,scene.data.body,content,undefined,pkg.runtimeProject.projectId,materialView(pkg.runtimeProject,pkg.assetData??{},pkg.publicToRuntime,urls));for(const id of scene.data.dialogueLineIds??[]){const line=session.content.entities.find(e=>e.id===id);if(line?.kind==='dialogue_line')richBody(pkg.runtimeProject,line.data.text,content,undefined,pkg.runtimeProject.projectId,materialView(pkg.runtimeProject,pkg.assetData??{},pkg.publicToRuntime,urls));}}
   for(const entity of session.content.entities){if(entity.status!=='confirmed'||entity.deletedAt)continue;if(entity.kind==='cue'&&presentationAnchorApplies(session.content,session.state,entity.data.anchor,{nodeId:node?.id,sceneId:scene?.id})){const p=document.createElement('p');p.textContent=`演出 ${entity.data.cueType} · ${entity.data.mediaTime??0} ms · ${JSON.stringify(entity.data.camera??{})}`;content.append(p);media(entity.data.attachmentId);}if(entity.kind==='storyboard_frame'&&presentationAnchorApplies(session.content,session.state,entity.data.anchor,{nodeId:node?.id,sceneId:scene?.id})){richBody(pkg.runtimeProject,entity.data.caption??[],content,undefined,pkg.runtimeProject.projectId,materialView(pkg.runtimeProject,pkg.assetData??{},pkg.publicToRuntime,urls));media(entity.data.finalAssetId??entity.data.referenceAssetId);}}
   const trace=document.createElement('p');trace.textContent=`${session.status} · 進行 ${requests.length}回 · ${gameMode(actions)}`;path.append(trace);const step=async(request:TrialRequest={})=>{if(requests.length>=10000)throw Error('一経路10,000遷移が上限です。');const trigger=node?.data.trigger;if(trigger&&!confirm(`宣言された入力「${trigger.eventKey||trigger.event}」をゲームへ渡しますか。`))return;const submitted={...request,worldTick:initialTick,...trigger?{event:{triggerId:trigger.id||node!.id,event:trigger.event,eventKey:trigger.eventKey,occurrenceId:crypto.randomUUID()}}:{}},before=session!.trace.length,next=stepTrial(pkg!.runtimeProject,session!,submitted);session=next;if(next.trace.length>before)requests.push(submitted);status.textContent=[next.status,...next.issues.map(i=>i.message)].join(' · ');};if(session.status==='ready'){if((node?.data.executionPolicy??(node?.data.nodeType==='automatic'?'first_match':'manual_choice'))!=='manual_choice'||node?.data.nodeType==='call'||node?.data.nodeType==='exit')button(path,'ゲームの規則で次へ',()=>step());else for(const choice of getTrialChoices(pkg.runtimeProject,session))button(path,choice.label,()=>step({edgeId:choice.edgeId}),choice.result!=='true');}
   button(path,'受領hash・実結果の証跡を保存',async()=>{const receipt=await buildGameReceipt(pkg!,{entryId:entries.value,worldTick:initialTick,actions,requests}),blob=new Blob([jsonBytes(receipt).slice().buffer as ArrayBuffer],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='game-receipt.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
  }
  (globalThis as any).GameReceiverState=()=>({actions:structuredClone(actions),requests:structuredClone(requests),session:session?structuredClone(session):undefined});
 }
 file.onchange=async()=>{const selected=file.files?.[0];if(!selected||busy)return;busy=true;try{if(selected.size>64*1024*1024)throw Error('受取JSONは64 MiB以下で選んでください。');pkg=await receiveGamePackage(parseStrictJson(new Uint8Array(await selected.arrayBuffer()),'runtime.json'));actions=[];requests=[];session=undefined;entries.replaceChildren();for(const id of declaredEntrypoints(pkg.runtimeProject)){const option=document.createElement('option');option.value=id;option.textContent=pkg.runtimeProject.entities.find(e=>e.id===id)?.name??id;entries.append(option);}status.textContent=`仕様scenario-runtime1.1.0 · 受領hash ${await sha256(jsonBytes(pkg))}`;}catch(cause){pkg=undefined;status.textContent=(cause as Error).message;}finally{busy=false;render();}};
}
